          <ArticleSkeleton v-if="loading && articles.length === 0" :count="4" />
          <div v-else-if="feedArticles.length" class="article-grid"><article v-for="(article, index) in feedArticles" :key="article.id" class="article-card" @click="goToArticle(article.id)"><div class="card-topline"><span>{{ String(index + 2).padStart(2, '0') }}</span><span class="card-category">{{ article.category_name || '未分类' }}</span></div><h3>{{ article.title }}</h3><p>{{ article.summary || '一段值得留下的记录。' }}</p><footer><time><el-icon><Clock /></el-icon>{{ formatDate(article.created_at) }}</time><span><el-icon><View /></el-icon>{{ article.view_count || 0 }}</span></footer></article></div>
